import gurobipy as gp
from gurobipy import GRB
shelves = []
capacity = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'ShelfID' in v and 'Capacity' in v:
        shelf = str(v['ShelfID'])
        shelves.append(shelf)
        capacity[shelf] = float(v['Capacity'])
products = []
value = {}
weight = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'ProductName' in v and 'Value' in v and ('Weight' in v):
        pname = v['ProductName']
        products.append(pname)
        value[pname] = float(v['Value'])
        weight[pname] = float(v['Weight'])
if len(shelves) == 0 or len(products) == 0:
    raise ValueError('Missing shelves or products data.')
for s in shelves:
    if s not in capacity:
        raise ValueError(f'Missing capacity for shelf {s}')
for p in products:
    if p not in value or p not in weight:
        raise ValueError(f'Missing value or weight for product {p}')
m = gp.Model('Retail_Display_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[p] * x[s, p] for s in shelves for p in products)), GRB.MAXIMIZE)
for s in shelves:
    m.addConstr(gp.quicksum((weight[p] * x[s, p] for p in products)) <= capacity[s], name=f'cap_{s}')
first_product = products[0]
m.addConstr(gp.quicksum((x[s, first_product] for s in shelves)) >= 5, name='min_smartphone')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for s in shelves:
        for p in products:
            var = x[s, p]
            print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')